import{_ as s,l as n,o as e,c as i,v as t,p as o,x as l,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"多级页表","description":"","frontmatter":{"title":"多级页表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/multi-level-page-table.md","filePath":"cs/multi-level-page-table.md","lastUpdated":1789023840000}'),h={name:"cs/multi-level-page-table.md"};function B(A,a,P,m,_,E){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="多级页表" tabindex="-1">多级页表 <a class="header-anchor" href="#多级页表" aria-label="Permalink to &quot;多级页表&quot;">​</a></h1><div class="epigraph"><p>单级页表按虚拟页号铺成一张大数组，空洞也占满物理内存；分级以后，空的那一段连中间页都不分配。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/tlb-translate">上一课</a>让常见翻译停在 TLB。TLB 缺失仍要查页表。<a href="/cs/tlb-translate">虚拟内存分页</a>把页表写成 VPN 的数组：48 位虚拟地址、4 KiB 页时，单级表有两亿项，不能为每个进程各留一份连续物理数组。本课不重讲 TLB 命中路径。缺口是：页表自己的空间。本课只交出多级页表：VPN 切成几段，逐级索引。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>程序通常只用地址空间里几块（代码、堆、栈），中间是巨洞。单级表无法对洞不分配：数组下标必须覆盖整个 VPN。缺口不是更大的 TLB，而是<strong>树：根物理页常驻，下一级页只在该段有映射时才存在</strong>。</p><p>走访次数等于级数。TLB 缺失代价从「一次 DRAM 读」变成「三次或四次」。本课接受这笔费用，因为强制缺失相对进程寿命仍少。</p><p><span class="marginnote">RISC-V Sv39 三级、Sv48 四级是同一思想的参数。本课不绑死某一特权规范编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 VPN 分成 \\(k\\) 段。第一段索引根目录，得到下一级表的 PPN；下一段再索引，直到叶页表项给出最终 PPN 与权限。任一级有效位为 0 即缺页，不必走到叶。</p>',9)),(e(),o(c,null,{default:l(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20VPN%5B%22VPN%20%E5%88%86%E6%AE%B5%22%5D%20--%3E%20L1%5B%22%E6%A0%B9%E7%9B%AE%E5%BD%95%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E4%B8%AD%E9%97%B4%E9%A1%B5%E8%A1%A8%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E5%8F%B6%E9%A1%B5%E8%A1%A8%E9%A1%B9%20%E2%86%92%20PPN%22%5D%0A%20%20L1%20--%3E%7C%22%E6%97%A0%E6%95%88%22%7C%20PF%5B%22%E7%BC%BA%E9%A1%B5%22%5D%0A%20%20L2%20--%3E%7C%22%E6%97%A0%E6%95%88%22%7C%20PF%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>硬件走访或软件走访都按这棵树。TLB 填入的仍是叶结果：VPN 到最终 PPN，中间节点不必进 TLB。巨型页（把中间项标成直接映射一大块）是减少级数与 TLB 压力的附录，本课只点名存在。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多级把页表容量变成与已映射页数成正比，而不是与虚拟空间成正比。代价是 TLB 缺失的多次访存，这些访存自己也走 cache，吃<a href="/cs/locality-principle">局部性原理</a>。内核分配中间页失败与用户缺页不同，但都经精确异常路径。</p><p>页表页本身也有物理地址，可以再被 cache。一致性问题尚未针对多核：本课仍默认单核改页表后刷 TLB。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入反置页表、不讨论分段与页混合的历史方案。也不把文件系统的目录树当成同一对象——只是「稀疏数组用树存」这一层相似。后课一致性会问：多核各自 TLB 与页表缓存如何作废。</p><p>后课默认：页表是多级的；TLB 命中仍一拍。谈到走表，允许若干次访存。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单级表按虚拟空间铺开；多级只为有映射的段分配中间页。</li><li>TLB 缺失代价随级数增加；叶项才进 TLB。</li><li>多核下各份副本如何一致，是下一课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const L=s(h,[["render",B]]);export{u as __pageData,L as default};
